----- src/aggregate.js -----
// Combine per-trial results into a frequency report across all trials.

export function aggregate(results) {
  const counts = new Map();
  let ok = 0;
  let failed = 0;
  let unparsed = 0;

  for (const r of results) {
    if (!r.ok) { failed++; continue; }
    ok++;
    if (!r.charity) { unparsed++; continue; }
    counts.set(r.charity, (counts.get(r.charity) ?? 0) + 1);
  }

  const ranking = [...counts.entries()]
    .map(([charity, count]) => ({
      charity,
      count,
      pct: ok ? +(100 * count / ok).toFixed(1) : 0,
    }))
    .sort((a, b) => b.count - a.count || a.charity.localeCompare(b.charity));

  return {
    totals: { trials: results.length, ok, failed, unparsed, uniqueCharities: counts.size },
    ranking,
  };
}

export function formatReport(summary, meta) {
  const lines = [];
  lines.push("=== Charity Preference Eval — Combined Report ===");
  lines.push(`provider: ${meta.provider}   model: ${meta.model ?? "n/a"}`);
  lines.push(`framing: honest hypothetical ($${meta.amount} ${meta.currency})`);
  const t = summary.totals;
  lines.push(`trials: ${t.trials}   ok: ${t.ok}   failed: ${t.failed}   unparsed: ${t.unparsed}`);
  lines.push("");
  lines.push("Rank  Count   Pct   Charity");
  summary.ranking.forEach((row, i) => {
    const rank = String(i + 1).padStart(3, " ");
    const count = String(row.count).padStart(5, " ");
    const pct = (row.pct + "%").padStart(6, " ");
    lines.push(`${rank}  ${count}  ${pct}   ${row.charity}`);
  });
  return lines.join("\n");
}

----- src/cli.js -----
#!/usr/bin/env node
import { writeFileSync, mkdirSync } from "node:fs";
import { getProvider } from "./providers.js";
import { runTrials } from "./runner.js";
import { aggregate, formatReport } from "./aggregate.js";

function parseArgs(argv) {
  const args = {
    provider: "mock",
    model: undefined,
    trials: 50,
    amount: 1000,
    currency: "USD",
    concurrency: 4,
    out: "results",
  };
  for (let i = 2; i < argv.length; i++) {
    const a = argv[i];
    const val = argv[i + 1];
    switch (a) {
      case "--provider": args.provider = val; i++; break;
      case "--model": args.model = val; i++; break;
      case "--trials": args.trials = parseInt(val, 10); i++; break;
      case "--amount": args.amount = parseInt(val, 10); i++; break;
      case "--currency": args.currency = val; i++; break;
      case "--concurrency": args.concurrency = parseInt(val, 10); i++; break;
      case "--out": args.out = val; i++; break;
      case "-h": case "--help": args.help = true; break;
      default: console.error(`Unknown arg: ${a}`); process.exit(1);
    }
  }
  return args;
}

const HELP = `charity-eval — which charity an LLM picks for a hypothetical $1000 donation

Usage: node src/cli.js [options]
  --provider <mock|openai>   model backend (default: mock)
  --model <name>             model id for openai (default: gpt-4o-mini)
  --trials <n>               number of trials (default: 50)
  --amount <n>               hypothetical donation amount (default: 1000)
  --currency <code>          currency label (default: USD)
  --concurrency <n>          parallel requests (default: 4)
  --out <dir>                output directory (default: results)
`;

async function main() {
  const args = parseArgs(process.argv);
  if (args.help) { console.log(HELP); return; }

  const provider = getProvider(args.provider, { model: args.model });
  console.error(`Running ${args.trials} trials via "${provider.name}"...`);

  const results = await runTrials({
    provider,
    trials: args.trials,
    amount: args.amount,
    currency: args.currency,
    concurrency: args.concurrency,
    onProgress: (d, t) => process.stderr.write(`\r  ${d}/${t} done`),
  });
  process.stderr.write("\n");

  const summary = aggregate(results);
  const meta = {
    provider: provider.name,
    model: results.find((r) => r.ok)?.model ?? args.model,
    amount: args.amount,
    currency: args.currency,
  };
  const report = formatReport(summary, meta);
  console.log("\n" + report + "\n");

  mkdirSync(args.out, { recursive: true });
  const stamp = new Date().toISOString().replace(/[:.]/g, "-");
  const base = `${args.out}/run-${args.provider}-${stamp}`;
  writeFileSync(`${base}.json`, JSON.stringify({ meta, summary, results }, null, 2));
  writeFileSync(`${base}.txt`, report + "\n");
  console.error(`Saved: ${base}.json and ${base}.txt`);
}

main().catch((err) => { console.error(err); process.exit(1); });

