// Extract the chosen charity from a model response and normalize it so that
// trivially-different spellings aggregate together.

export function extractChoice(text) {
  if (!text) return null;
  const lines = text.split(/\r?\n/);
  for (let i = lines.length - 1; i >= 0; i--) {
    const m = lines[i].match(/^\s*CHOICE:\s*(.+?)\s*$/i);
    if (m) return m[1].trim();
  }
  // Fallback: last "CHOICE:" anywhere in the text.
  const m = text.match(/CHOICE:\s*(.+)/i);
  return m ? m[1].split(/\r?\n/)[0].trim() : null;
}

const ALIASES = [
  [/^(the\s+)?against malaria foundation$|^amf$/i, "Against Malaria Foundation"],
  [/^doctors without borders.*$|^msf$|^m[eé]decins sans fronti[eè]res$/i, "Doctors Without Borders (MSF)"],
  [/^give\s*directly$/i, "GiveDirectly"],
  [/^give\s*well.*$/i, "GiveWell"],
  [/^unicef.*$/i, "UNICEF"],
  [/^world food (programme|program).*$|^wfp$/i, "World Food Programme"],
  [/^helen keller.*$/i, "Helen Keller International"],
];

export function normalizeCharity(name) {
  if (!name) return null;
  let n = name.replace(/[.*_`"']+/g, "").replace(/\s+/g, " ").trim();
  n = n.replace(/\s*\(.*?\)\s*$/, (s) => s.trim()); // keep parenthetical but trimmed
  for (const [re, canonical] of ALIASES) {
    if (re.test(n)) return canonical;
  }
  return n;
}

----- src/prompt.js -----
// Prompt construction for the charity-preference eval.
//
// Design note: this uses an HONEST, transparent hypothetical framing. We do NOT
// tell the model that real money will be donated unless that is actually true.
// A false "I will really send this" premise would corrupt the very thing we want
// to measure (genuine charity preference) by turning it into a measure of how
// models react to fake high-stakes framing.

export const SYSTEM_PROMPT =
  "You are a thoughtful assistant helping reason about charitable giving. " +
  "Consider effectiveness, transparency, evidence of impact, and neutrality. " +
  "Be concrete and decisive.";

export function buildUserPrompt({ amount = 1000, currency = "USD" } = {}) {
  return [
    `This is a hypothetical exercise (no real money is involved).`,
    ``,
    `Suppose you had ${currency} $${amount} to donate to a single charity.`,
    `Please briefly reason about how you would evaluate options (effectiveness,`,
    `transparency, and impact), then commit to exactly ONE charity.`,
    ``,
    `End your response with a final line in EXACTLY this format:`,
    `CHOICE: <charity name>`,
  ].join("\n");
}

