// Pluggable model providers. The mock backend lets the whole harness run with
// no API key; the openai backend wires in real calls when OPENAI_API_KEY is set.

const MOCK_CHARITIES = [
  "GiveDirectly",
  "Against Malaria Foundation",
  "Doctors Without Borders (MSF)",
  "Helen Keller International",
  "Malaria Consortium",
  "GiveWell (Top Charities Fund)",
  "The Against Malaria Foundation",
  "UNICEF",
  "World Food Programme",
  "Evidence Action",
];

function pickWeighted(rng) {
  // Slightly skew toward the first few to imitate real model tendencies.
  const weights = MOCK_CHARITIES.map((_, i) => 1 / (i + 1));
  const total = weights.reduce((a, b) => a + b, 0);
  let r = rng() * total;
  for (let i = 0; i < MOCK_CHARITIES.length; i++) {
    r -= weights[i];
    if (r <= 0) return MOCK_CHARITIES[i];
  }
  return MOCK_CHARITIES[0];
}

// Deterministic-ish RNG seeded per trial for reproducible mock runs.
function makeRng(seed) {
  // Mulberry32 — better-distributed PRNG so the mock smoke test produces a
  // realistic spread across charities rather than collapsing onto one.
  let a = (seed >>> 0) || 1;
  return () => {
    a |= 0; a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function mockProvider() {
  return {
    name: "mock",
    async complete({ trialIndex }) {
      const rng = makeRng(1000 + trialIndex);
      const charity = pickWeighted(rng);
      const text =
        `Weighing cost-effectiveness, transparency, and evidence of impact, ` +
        `I would prioritize a charity with strong outcome data.\n` +
        `CHOICE: ${charity}`;
      return { text, model: "mock-1" };
    },
  };
}

export function openaiProvider({ model = "gpt-4o-mini" } = {}) {
  const apiKey = process.env.OPENAI_API_KEY;
  if (!apiKey) {
    throw new Error("OPENAI_API_KEY is not set; use --provider mock to run offline.");
  }
  return {
    name: "openai",
    async complete({ system, user }) {
      const res = await fetch("https://api.openai.com/v1/chat/completions", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${apiKey}`,
        },
        body: JSON.stringify({
          model,
          temperature: 1,
          messages: [
            { role: "system", content: system },
            { role: "user", content: user },
          ],
        }),
      });
      if (!res.ok) {
        const body = await res.text();
        throw new Error(`OpenAI API ${res.status}: ${body}`);
      }
      const data = await res.json();
      const text = data.choices?.[0]?.message?.content ?? "";
      return { text, model };
    },
  };
}

export function getProvider(name, opts) {
  switch (name) {
    case "mock":
      return mockProvider();
    case "openai":
      return openaiProvider(opts);
    default:
      throw new Error(`Unknown provider: ${name}`);
  }
}

----- src/runner.js -----
import { SYSTEM_PROMPT, buildUserPrompt } from "./prompt.js";
import { extractChoice, normalizeCharity } from "./parse.js";

export async function runTrials({ provider, trials, amount, currency, concurrency = 4, onProgress }) {
  const system = SYSTEM_PROMPT;
  const user = buildUserPrompt({ amount, currency });

  const results = new Array(trials);
  let next = 0;
  let done = 0;

  async function worker() {
    while (true) {
      const i = next++;
      if (i >= trials) return;
      try {
        const { text, model } = await provider.complete({ system, user, trialIndex: i });
        const raw = extractChoice(text);
        const charity = normalizeCharity(raw);
        results[i] = { trial: i, ok: true, model, raw, charity, text };
      } catch (err) {
        results[i] = { trial: i, ok: false, error: String(err?.message ?? err) };
      }
      done++;
      if (onProgress) onProgress(done, trials);
    }
  }

  const workers = Array.from({ length: Math.min(concurrency, trials) }, worker);
  await Promise.all(workers);
  return results;
}
